import { Player } from '@lottiefiles/react-lottie-player';
import { Fragment } from 'react';
import { 완료Context } from '~/widgets/exchange-remittance-funnel/model/schemas';
import { useSetHeaderLeft } from '~/widgets/sub-layout/use-sub-layout';
import { useComBankInfo } from '~/entities/comcode/lib/use-com-bank-info';
import { PhaseType } from '~/entities/exchange/model/constants';
import { ResultContainer } from '~/entities/exchange-complete/ui/result-container';
import { ConfirmInfo } from '~/entities/exchange-input-confirm/ui/confirm-info';
import { findTokenItemById, getTokenItemLabel } from '~/entities/user';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { getExchangeTransactionLabel } from '~/entities/wallet/lib/get-trnsc-type-label';
import lottieC from '~/shared/assets/img/lottie/checking_2.json';
import i18n from '~/shared/i18n/i18n';
import { PATHS } from '~/shared/routes/paths';

type CompletePageProps = {
  context: 완료Context;
  onNext: (params: 완료Context) => void;
  onError: (error: Error) => void;
};

export const CompletePage = ({ onNext, onError, context }: CompletePageProps) => {
  const moveToBegin = () => {
    if (window.ReactNativeWebView) {
      window.ReactNativeWebView.postMessage(JSON.stringify({ type: 'CLOSE_POPUP' }));
    }
    onNext({
      ...context,
    });
  };

  const moveToHistory = () => {
    if (window.ReactNativeWebView) {
      window.ReactNativeWebView.postMessage(JSON.stringify({ type: 'CLOSE_POPUP' }));
    }
    onNext({
      ...context,
      redirectPath: PATHS.myWallet.history,
    });
  };

  const transactionLabel = getExchangeTransactionLabel(context.trnscTypeCd);

  useSetHeaderLeft(<></>);

  const { data: userRes } = useGetUserInfoQuery();
  const tokenItem = findTokenItemById(userRes?.tbCstmrMastr?.tokenList, context.tokenId);
  const usingTokenLabel = getTokenItemLabel(tokenItem);
  const tokenBankCode = tokenItem.bankCd ?? '';
  const { shortBankName: tokenBankShortName } = useComBankInfo(tokenBankCode);
  const tokenBankLabel = tokenBankShortName ?? '';
  const { shortBankName: recipientBankName } = useComBankInfo(context.recipientData?.insttCd ?? '');

  return (
    <div className="wrap bgw">
      <div className="content sub has-btm-btn">
        <ConfirmInfo amount={Number(context.trnscAmt)} phase={PhaseType.Complete} transactionLabel={transactionLabel}>
          <Fragment>
            {i18n.t('text:toX', { x: context.personNm })}
            <br />
            <button type="button" className={`wallet-account no-btn dark ${context.walletInsttCd}`}>
              {recipientBankName} {context.aliasNm}
            </button>
            {usingTokenLabel && <span className="token">{usingTokenLabel}</span>}
          </Fragment>
        </ConfirmInfo>
        <div className="result-area">
          <div className="process">
            <div id="lottieC">
              <Player src={lottieC} background="transparent" autoplay={true} speed={1} keepLastFrame={true} />
            </div>
          </div>
          <ResultContainer trnscTypeCd={context.trnscTypeCd}>
            <Fragment>
              <li className="exc-type">
                <span>{i18n.t('walletToUse')}</span>
                <b>
                  {/* {usingTokenLabel} | {tokenBankLabel} */}
                  {decodeURIComponent(tokenBankLabel)} | {context.reqAliasNm}
                </b>
              </li>
              <li className="exc-type">
                <span>{i18n.t('recipient')}</span>
                <div className="exc-trans">
                  <div className="exc-trans-box to trans">
                    <p>{context.personNm}</p>
                    <span>
                      {recipientBankName} {context.aliasNm}
                    </span>
                  </div>
                </div>
              </li>
            </Fragment>
          </ResultContainer>
        </div>
      </div>
      <div className="btm-btn-area confirm half" id="result-btn-area">
        <button type="button" className="btm-btn" onClick={moveToHistory}>
          {i18n.t('viewAllUsageHistory')}
        </button>
        <button type="button" className="btm-btn app" onClick={moveToBegin}>
          {i18n.t('confirm')}
        </button>
      </div>
    </div>
  );
};
